      fn("listBoardColumns", "(orgId: OrgId, projectId: ProjectId): Promise<readonly IssueBoardColumn[]>"),
      fn("countIssues", "(orgId: OrgId, projectId: ProjectId, scope?: ArchiveScope): Promise<number>"),

