  }

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const suspended = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

/** Reverses `suspendMember`. Never at risk of the last-owner invariant: it only ever adds an owner back. */
export async function reinstateMember(
  actor: Actor,
  input: ReinstateMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (!isLive(member)) {
    throw new NotFoundError("Member", input.memberId);
  }

  assertCan(actor, "member:remove", memberResource(member));
  assertNotSelfAndNotOutranked(actor, member, "reinstate");

  if (member.status !== "suspended") {
    return member;
  }

  const reinstated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
