 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner who is not suspended. Exported because the demote, remove
 * and suspend paths all need it, and the invariant must not be stated thrice.
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
