import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as memberRepo from "@/server/repositories/member-repository";
import * as organizationRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as memberService from "@/server/services/member-service";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as notificationService from "@/server/services/notification-service";
import { registerActivityListeners, listActivity } from "@/server/services/activity-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detachActivity: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("suspend/reinstate verification", () => {
  it("full lifecycle", async () => {
    const tenant = await createTenant("suspend-verify", "growth");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!admin) throw new Error("missing admin");

    let suspendedEvent: unknown = null;
    const offSuspended = subscribe("member.suspended", (p) => (suspendedEvent = p));

    const suspended = await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });
    offSuspended();

    expect(suspended.status).toBe("suspended");
    expect(suspendedEvent).toMatchObject({
      orgId: tenant.org.id,
      memberId: admin.id,
      userId: tenant.userIds.admin,
    });

    // idempotent
    let secondEvent: unknown = null;
    const off2 = subscribe("member.suspended", (p) => (secondEvent = p));
    const again = await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });
    off2();
    expect(again.status).toBe("suspended");
    expect(secondEvent).toBeNull();

    // resolveActor returns null for suspended
    expect(await memberService.resolveActor(tenant.userIds.admin, tenant.org.id)).toBeNull();

    // seat still counted
    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(4);
    const usage = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.seatsUsed).toBe(4);

    // org switcher excludes suspended member's org
    const orgs = await organizationRepo.listOrgsForUser(tenant.userIds.admin);
    expect(orgs.find((o) => o.id === tenant.org.id)).toBeUndefined();

    // self-suspend forbidden
    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: (await memberRepo.findMember(tenant.org.id, tenant.userIds.owner))!.id,
      }),
    ).rejects.toThrow(/yourself/);

    // outrank forbidden: admin (suspended, but let's use member role actor) member cannot suspend owner
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    await expect(
      memberService.suspendMember(tenant.actors.member, {
        orgId: tenant.org.id,
        memberId: ownerMember!.id,
      }),
    ).rejects.toThrow();

    // assigning issue to suspended member throws MemberSuspendedError
    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Assign to suspended",
          assigneeId: tenant.userIds.admin,
        }),
      ),
    ).rejects.toBeInstanceOf(memberService.MemberSuspendedError);

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Reassign attempt" }),
    );
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.admin,
      }),
    ).rejects.toBeInstanceOf(memberService.MemberSuspendedError);

    // mention of suspended member is dropped
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "hey @admin check this",
      parentId: null,
      mentionedUserIds: [tenant.userIds.admin],
    });
    expect(comment.mentionedUserIds).not.toContain(tenant.userIds.admin);

    // notify() skips suspended recipient
    const rows = await notificationService.notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.admin, tenant.userIds.viewer],
      { title: "t", body: "b", href: "/x", actorId: null },
    );
    expect(rows.map((r) => r.recipientId)).not.toContain(tenant.userIds.admin);
    expect(rows.map((r) => r.recipientId)).toContain(tenant.userIds.viewer);

    // audit log recorded
    const activity = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["member.suspended"],
      limit: 10,
      cursor: null,
    });
    expect(activity.items).toHaveLength(1);
    expect(activity.items[0]).toMatchObject({
      subjectKind: "member",
      subjectId: admin.id,
      actorId: tenant.userIds.owner,
    });

    // reinstate
    let reinstatedEvent: unknown = null;
    const offR = subscribe("member.reinstated", (p) => (reinstatedEvent = p));
    const reinstated = await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });
    offR();
    expect(reinstated.status).toBe("active");
    expect(reinstatedEvent).toMatchObject({ memberId: admin.id, userId: tenant.userIds.admin });

    expect(await memberService.resolveActor(tenant.userIds.admin, tenant.org.id)).not.toBeNull();
    const orgsAfter = await organizationRepo.listOrgsForUser(tenant.userIds.admin);
    expect(orgsAfter.find((o) => o.id === tenant.org.id)).not.toBeUndefined();

    // last-owner invariant extends to suspend
    const soloTenant = await createTenant("suspend-lastowner", "growth");
    const soloOwnerMember = await memberRepo.findMember(soloTenant.org.id, soloTenant.userIds.owner);
    const soloAdminMember = await memberRepo.findMember(soloTenant.org.id, soloTenant.userIds.admin);
    await memberService.updateMemberRole(soloTenant.actors.owner, {
      orgId: soloTenant.org.id,
      memberId: soloAdminMember!.id,
      role: "owner",
    });
    // now two owners; suspend the original owner via the new owner actor
    const newOwnerActor = { ...soloTenant.actors.admin, role: "owner" as const };
    await memberService.suspendMember(newOwnerActor, {
      orgId: soloTenant.org.id,
      memberId: soloOwnerMember!.id,
    });
    // only one active owner remains (soloAdminMember, now owner); suspending them must fail
    await expect(
      memberService.suspendMember({ ...soloTenant.actors.viewer, role: "owner" as const, userId: (await memberRepo.findMember(soloTenant.org.id, soloTenant.userIds.viewer))!.userId }, {
        orgId: soloTenant.org.id,
        memberId: soloAdminMember!.id,
      }),
    ).rejects.toThrow(/at least one owner/);
  });

  it("removed member cannot be suspended (NotFoundError)", async () => {
    const tenant = await createTenant("suspend-removed", "growth");
    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewerMember!.id,
    });

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewerMember!.id,
      }),
    ).rejects.toThrow(/not found/i);
  });
});

